from itertools import combinations
V=list('abcdefghijkl')
idx={v:i for i,v in enumerate(V)}
edges=[('a','b'),('b','c'),('c','d'),('d','e'),('e','f'),('f','g'),('g','h'),('h','i'),('i','j'),('j','k'),('k','l'),('l','a'),('a','g'),('b','h'),('c','i'),('d','j'),('e','k'),('f','l'),('a','d'),('b','e'),('c','f'),('g','j'),('h','k'),('i','l')]
E={tuple(sorted((idx[u],idx[v]))) for u,v in edges}

def indep(S):
    S=list(S)
    for i in range(len(S)):
        for j in range(i+1,len(S)):
            if tuple(sorted((S[i],S[j]))) in E:
                return False
    return True
best=[]
